      if (claimHash === expectedClaimHash) {
        claimResolveState.sendSnapshot.status = true;
        claimResolveState.sendSnapshot.txHash = sentSnapshotFromGraph.txHash;
      } else {
        return claimResolveState;
      }
    } else {
      return claimResolveState;
    }
  }

  const status = await fetchMessageStatus(claimResolveState.sendSnapshot.txHash, veaInboxProvider, veaOutboxProvider);
  claimResolveState.execution.status = status;

  return claimResolveState;
};

/**
 * Check a reconstructed claim against the outbox's own claim hash.
 *
 * `honest` is not carried by any event, so it is recovered by trying each of the
 * three possible values. The *matching variant* is returned rather than a
 * boolean: the caller needs the struct that actually hashes to `claimHash`,
 * since every contract call taking a claim re-hashes it and reverts on mismatch.
 *
 * @returns The claim variant that hashes to `claimHash`, or null if none does
 */
const verifyClaimHash = ({ claim, claimHash }: { claim: ClaimStruct; claimHash: string }): ClaimStruct | null => {
  const candidates: ClaimStruct[] = [
    { ...claim, honest: ClaimHonestState.NONE },
    { ...claim, honest: ClaimHonestState.CLAIMER },
    { ...claim, honest: ClaimHonestState.CHALLENGER },
  ];
  return candidates.find((candidate) => hashClaim(candidate) === claimHash) ?? null;
};

/**
 * Hashes the claim data.
 *
 * @param claim - The claim data to be hashed
 *
 * @returns The hash of the claim data
 *
 */
const hashClaim = (claim: ClaimStruct) => {
  return ethers.solidityPackedKeccak256(
    ["bytes32", "address", "uint32", "uint32", "uint32", "uint8", "address"],
    [
      claim.stateRoot,
      claim.claimer,
      claim.timestampClaimed,
      claim.timestampVerification,
      claim.blocknumberVerification,
      claim.honest,
      claim.challenger,
    ]
  );
};

/**
 * Locate the `Claim` argument in a parsed `sendSnapshot` call.
 *
 * The argument list is route-dependent:
 *   arbToEth              `sendSnapshot(uint256 _epoch, Claim _claim)`
 *   arbToGnosis/gnosisToArb `sendSnapshot(uint256 _epoch, uint256 _gasLimit, Claim _claim)`
 *
 * so a hardcoded index is wrong on one of them. The claim is the only
 * tuple-typed parameter in every variant, so the index is derived from the
 * parsed function fragment rather than from the route - no chainId plumbing,
 * and a future signature change cannot silently reintroduce the bug.
 *
 * @returns The index of the tuple parameter, or -1 if the fragment has none
 */
const claimArgIndex = (fragment: any): number => {
  const inputs = fragment?.inputs ?? [];
  // Searched from the end: the claim is always the last parameter.
  for (let i = inputs.length - 1; i >= 0; i--) {
    const input = inputs[i];
    if (input?.baseType === "tuple" || input?.type === "tuple") return i;
  }
  return -1;
};

/**
 * Recompute the claim hash carried by a `sendSnapshot` transaction.
 *
 * Reading the wrong argument hashes the gas limit instead of the claim, so the
 * result never matches the outbox's `claimHashes[epoch]` and a snapshot that was
 * in fact sent looks unsent forever - the challenger then keeps re-sending it.
 *
 * @returns The claim hash the transaction carries, or null if it cannot be read
 */
const getSentSnapshotData = async (
  txHash: string,
  provider: JsonRpcProvider,
  inboxInterface: any
): Promise<string | null> => {
  const tx = await provider.getTransaction(txHash);
  if (!tx) return null;

  // Parse the transaction calldata to identify function + args
  const parsed = inboxInterface.parseTransaction({ data: tx.data });
  // ethers v6 returns null for calldata no fragment matches; never throw here,
  // an unparsable tx is a "not sent" answer, not a dead route task.
  if (!parsed) return null;
  const index = claimArgIndex(parsed.fragment);
  if (index === -1) return null;
  const claimTuple = parsed.args[index] as unknown as ClaimStruct;
  const expectedClaimHash = hashClaim(claimTuple);
  return expectedClaimHash;
};

export { getClaim, hashClaim, getClaimResolveState, getSentSnapshotData, ClaimHonestState };

